window.AUTH=window.AUTH||{};window.AUTH["11-184"]={"d":"11-184","id":"2012/11-184","n":"Kloeckner v Solis","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for respondent","date":"","url":"https://www.justice.gov/osg/media/224731/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/kloeckner-v-solis-brief-merits","n":69}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep568/usrep568041/usrep568041.pdf","tr":true,"items":[{"t":"case","label":"Ballentine v. MSPB","cite":"738 F.2d 1244","y":1984,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/738/1244/","op":1,"ar":3,"by":{"0":"2, 3"}},{"t":"case","label":"Chandler v. Roudebush","cite":"425 U.S. 840","y":1976,"id":"1975/74-1599","sc":1,"ar":1,"sum":"The plain meaning of the statute, reinforced by the legislative history of the 1972 amendments, compels the conclusion that federal employees have the same right to a trial de novo as is enjoyed by private-sector or state-government employees under the amended Civil Rights Act of 1964. Pp. 843-864. 515 F. 2d 251, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Cloutier v. USPS","cite":"89 M.S.P.R. 411","y":2001,"url":"https://www.courtlistener.com/c/M.S.P.R./89/411/","by":{"0":"47"}},{"t":"case","label":"Cutts v. Fowler","cite":"692 F.2d 138","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/692/138/","by":{"0":"3"}},{"t":"case","label":"Downey v. Runyon","cite":"160 F.3d 139","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/160/139/","op":1,"by":{"0":"25"}},{"t":"case","label":"Doyal v. Marsh","cite":"777 F.2d 1526","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/777/1526/","sum":"Noting that courts of appeals agree that district courts reviewing mixed cases should not bifurcate an employee’s discrimination and nondiscrimination claims.","sumSrc":"brief:0","by":{"0":"30"}},{"t":"case","label":"Elgin v. Department of the Treasury","cite":"132 S. Ct. 2126","y":2012,"id":"2011/11-45","sc":1,"op":1,"ar":3,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"20, 31"}},{"t":"case","label":"Fornaro v. James","cite":"416 F.3d 63","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/416/63/","by":{"0":"2"}},{"t":"case","label":"Graham v. Ashcroft","cite":"358 F.3d 931","y":2004,"url":"https://www.courtlistener.com/c/F.3d/358/931/","by":{"0":"2"}},{"t":"case","label":"Harms v. IRS","cite":"321 F.3d 1001","y":2003,"url":"https://www.courtlistener.com/c/F.3d/321/1001/","op":1,"ar":1,"by":{"0":"25"}},{"t":"case","label":"Lawrence v. Department of Interior","cite":"525 F.3d 916","y":2008,"url":"https://www.courtlistener.com/c/F.3d/525/916/","by":{"0":"8"}},{"t":"case","label":"Lehman v. Morrissey","cite":"779 F.2d 526","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/779/526/","by":{"0":"2"}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"ar":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Moore v. USPS","cite":"91 M.S.P.R. 277","y":2002,"url":"https://www.courtlistener.com/c/M.S.P.R./91/277/","by":{"0":"47"}},{"t":"case","label":"Sher v. United States Dep’t of Veterans Affairs","cite":"488 F.3d 489","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/488/489/","by":{"0":"8"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"op":1,"ar":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 6, 32, 33"}},{"t":"case","label":"United States v. Hohri","cite":"482 U.S. 64","y":1987,"id":"1986/86-510","sc":1,"sum":"The Federal Circuit rather than the appropriate regional court of appeals has jurisdiction over an appeal from a district court's decision of a \"mixed\" case raising both a nontax Little Tucker Act claim and an FTCA claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Williams v. Wynne","cite":"533 F.3d 360","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/533/360/","op":1,"by":{"0":"8"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"passim"}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(b)","(c)"],"stext":{"head":"§633a. Nondiscrimination on account of age in Federal Government employment","paras":[[0,"(a) Federal agencies affected"],[0,"All personnel actions affecting employees or applicants for employment who are at least 40 years of age (except personnel actions with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units in the government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on age."],[0,"(b) Enforcement by Equal Employment Opportunity Commission and by Librarian of Congress in the Library of Congress; remedies; rules, regulations, orders, and instructions of Commission: compliance by Federal agencies; powers and duties of Commission; notification of final action on complaint of discrimination; exemptions: bona fide occupational qualification"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission is authorized to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without backpay, as will effectuate the policies of this section. The Equal Employment Opportunity Commission shall issue such rules, regulations, orders, and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the review and evaluation of the operation of all agency programs designed to carry out the policy of this section, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each department, agency, or unit referred to in subsection (a);"],[1,"(2) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to nondiscrimination in employment on account of age; and"],[1,"(3) provide for the acceptance and processing of complaints of discrimination in Federal employment on account of age."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions of the Equal Employment Opportunity Commission which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. Reasonable exemptions to the provisions of this section may be established by the Commission but only when the Commission has established a maximum age requirement on the basis of a determination that age is a bona fide occupational qualification necessary to the performance of the duties of the position. With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil actions; jurisdiction; relief"],[0,"Any person aggrieved may bring a civil action in any Federal district court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter."],[0,"(d) Notice to Commission; time of notice; Commission notification of prospective defendants; Commission elimination of unlawful practices"],[0,"When the individual has not filed a complaint concerning age discrimination with the Commission, no civil action may be commenced by any individual under this section until the individual has given the Commission not less than thirty days' notice of an intent to file such action. Such notice shall be filed within one hundred and eighty days after the alleged unlawful practice occurred. Upon receiving a notice of intent to sue, the Commission shall promptly notify all persons named therein as prospective defendants in the action and take any appropriate action to assure the elimination of any unlawful practice."],[0,"(e) Duty of Government agency or official"],[0,"Nothing contained in this section shall relieve any Government agency or official of the responsibility to assure nondiscrimination on account of age in employment as required under any provision of Federal law."],[0,"(f) Applicability of statutory provisions to personnel action of Federal departments, etc."],[0,"Any personnel action of any department, agency, or other entity referred to in subsection (a) of this section shall not be subject to, or affected by, any provision of this chapter, other than the provisions of sections 626(d)(3) and 631(b) of this title and the provisions of this section."],[0,"(g) Study and report to President and Congress by Equal Employment Opportunity Commission; scope"],[0,"(1) The Equal Employment Opportunity Commission shall undertake a study relating to the effects of the amendments made to this section by the Age Discrimination in Employment Act Amendments of 1978, and the effects of section 631(b) of this title."],[0,"(2) The Equal Employment Opportunity Commission shall transmit a report to the President and to the Congress containing the findings of the Commission resulting from the study of the Commission under paragraph (1) of this subsection. Such report shall be transmitted no later than January 1, 1980."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/633a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§633a. Nondiscrimination on account of age in Federal Government employment","tname":"Labor","by":{"0":"44, 44"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"passim"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(c)","(d)"],"by":{"0":"45, 44"}},{"t":"usc","label":"5 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/5/1101","stext":{"head":"§1101. Office of Personnel Management","paras":[[0,"The Office of Personnel Management is an independent establishment in the executive branch. The Office shall have an official seal, which shall be judicially noticed, and shall have its principal office in the District of Columbia, and may have field offices in other appropriate locations."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/1101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1101. Office of Personnel Management","tname":"Government Organization and Employees","by":{"0":"passim"}},{"t":"usc","label":"5 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/5/1201","stext":{"head":"§1201. Appointment of members of the Merit Systems Protection Board","paras":[[0,"The Merit Systems Protection Board is composed of 3 members appointed by the President, by and with the advice and consent of the Senate, not more than 2 of whom may be adherents of the same political party. The members of the Board shall be individuals who, by demonstrated ability, background, training, or experience are especially qualified to carry out the functions of the Board. No member of the Board may hold another office or position in the Government of the United States, except as otherwise provided by law or at the direction of the President. The Board shall have an official seal which shall be judicially noticed. The Board shall have its principal office in the District of Columbia and may have field offices in other appropriate locations."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/1201?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1201. Appointment of members of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"0":"3"}},{"t":"usc","label":"5 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/5/1204","subs":["(a)"],"stext":{"head":"§1204. Powers and functions of the Merit Systems Protection Board","paras":[[0,"(a) The Merit Systems Protection Board shall—"],[1,"(1) hear, adjudicate, or provide for the hearing or adjudication, of all matters within the jurisdiction of the Board under this title, chapter 43 of title 38, or any other law, rule, or regulation, and, subject to otherwise applicable provisions of law, take final action on any such matter;"],[1,"(2) order any Federal agency or employee to comply with any order or decision issued by the Board under the authority granted under paragraph (1) of this subsection and enforce compliance with any such order;"],[1,"(3) conduct, from time to time, special studies relating to the civil service and to other merit systems in the executive branch, and report to the President and to the Congress as to whether the public interest in a civil service free of prohibited personnel practices is being adequately protected; and"],[1,"(4) review, as provided in subsection (f), rules and regulations of the Office of Personnel Management."],[0,"(b)(1) Any member of the Merit Systems Protection Board, any administrative law judge appointed by the Board under section 3105 of this title, and any employee of the Board designated by the Board may administer oaths, examine witnesses, take depositions, and receive evidence."],[0,"(2) Any member of the Board, any administrative law judge appointed by the Board under section 3105, and any employee of the Board designated by the Board may, with respect to any individual—"],[1,"(A) issue subpoenas requiring the attendance and presentation of testimony of any such individual, and the production of documentary or other evidence from any place in the United States, any territory or possession of the United States, the Commonwealth of Puerto Rico, or the District of Columbia; and"],[1,"(B) order the taking of depositions from, and responses to written interrogatories by, any such individual."],[0,"(3) Witnesses (whether appearing voluntarily or under subpoena) shall be paid the same fee and mileage allowances which are paid subpoenaed witnesses in the courts of the United States."],[0,"(c) In the case of contumacy or failure to obey a subpoena issued under subsection (b)(2)(A) or section 1214(b), upon application by the Board, the United States district court for the district in which the person to whom the subpoena is addressed resides or is served may issue an order requiring such person to appear at any designated place to testify or to produce documentary or other evidence. Any failure to obey the order of the court may be punished by the court as a contempt thereof."],[0,"(d) A subpoena referred to in subsection (b)(2)(A) may, in the case of any individual outside the territorial jurisdiction of any court of the United States, be served in such manner as the Federal Rules of Civil Procedure prescribe for service of a subpoena in a foreign country. To the extent that the courts of the United States can assert jurisdiction over such individual, the United States District Court for the District of Columbia shall have the same jurisdiction to take any action respecting compliance under this subsection by such individual that such court would have if such individual were personally within the jurisdiction of such court."],[0,"(e)(1)(A) In any proceeding under subsection (a)(1), any member of the Board may request from the Director of the Office of Personnel Management an advisory opinion concerning the interpretation of any rule, regulation, or other policy directive promulgated by the Office of Personnel Management."],[0,"(B)(i) The Merit Systems Protection Board may, during an investigation by the Office of Special Counsel or during the pendency of any proceeding before the Board, issue any order which may be necessary to protect a witness or other individual from harassment, except that an agency (other than the Office of Special Counsel) may not request any such order with regard to an investigation by the Office of Special Counsel from the Board during such investigation."],[0,"(ii) An order issued under this subparagraph may be enforced in the same manner as provided for under paragraph (2) with respect to any order under subsection (a)(2)."],[0,"(2)(A) In enforcing compliance with any order under subsection (a)(2), the Board may order that any employee charged with complying with such order, other than an employee appointed by the President by and with the advice and consent of the Senate, shall not be entitled to receive payment for service as an employee during any period that the order has not been complied with. The Board shall certify to the Comptroller General of the United States that such an order has been issued and no payment shall be made out of the Treasury of the United States for any service specified in such order."],[0,"(B) The Board shall prescribe regulations under which any employee who is aggrieved by the failure of any other employee to comply with an order of the Board may petition the Board to exercise its authority under subparagraph (A)."],[0,"(3) In carrying out any study under subsection (a)(3), the Board shall make such inquiries as may be necessary and, unless otherwise prohibited by law, shall have access to personnel records or information collected by the Office of Personnel Management and may require additional reports from other agencies as needed."],[0,"(f)(1) At any time after the effective date of any rule or regulation issued by the Director of the Office of Personnel Management in carrying out functions under section 1103, the Board shall review any provision of such rule or regulation—"],[1,"(A) on its own motion;"],[1,"(B) on the granting by the Board, in its sole discretion, of any petition for such review filed with the Board by any interested person, after consideration of the petition by the Board; or"],[1,"(C) on the filing of a written complaint by the Special Counsel requesting such review."],[0,"(2) In reviewing any provision of any rule or regulation pursuant to this subsection, the Board shall declare such provision—"],[1,"(A) invalid on its face, if the Board determines that such provision would, if implemented by any agency, on its face, require any employee to violate section 2302(b); or"],[1,"(B) invalidly implemented by any agency, if the Board determines that such provision, as it has been implemented by the agency through any personnel action taken by the agency or through any policy adopted by the agency in conformity with such provision, has required any employee to violate section 2302(b)."],[0,"(3) The Director of the Office of Personnel Management, and the head of any agency implementing any provision of any rule or regulation under review pursuant to this subsection, shall have the right to participate in such review."],[0,"(4) The Board shall require any agency—"],[1,"(A) to cease compliance with any provisions of any rule or regulation which the Board declares under this subsection to be invalid on its face; and"],[1,"(B) to correct any invalid implementation by the agency of any provision of any rule or regulation which the Board declares under this subsection to have been invalidly implemented by the agency."],[0,"(g) The Board may delegate the performance of any of its administrative functions under this title to any employee of the Board."],[0,"(h) The Board shall have the authority to prescribe such regulations as may be necessary for the performance of its functions. The Board shall not issue advisory opinions. All regulations of the Board shall be published in the Federal Register."],[0,"(i) Except as provided in section 518 of title 28, relating to litigation before the Supreme Court, attorneys designated by the Chairman of the Board may appear for the Board, and represent the Board, in any civil action brought in connection with any function carried out by the Board pursuant to this title or as otherwise authorized by law."],[0,"(j) The Chairman of the Board may appoint such personnel as may be necessary to perform the functions of the Board. Any appointment made under this subsection shall comply with the provisions of this title, except that such appointment shall not be subject to the approval or supervision of the Office of Personnel Management or the Executive Office of the President (other than approval required under section 3324 or subchapter VIII of chapter 33)."],[0,"(k) The Board shall prepare and submit to the President, and, at the same time, to the appropriate committees of Congress, an annual budget of the expenses and other items relating to the Board which shall, as revised, be included as a separate item in the budget required to be transmitted to the Congress under section 1105 of title 31."],[0,"(l) The Board shall submit to the President, and, at the same time, to each House of the Congress, any legislative recommendations of the Board relating to any of its functions under this title."],[0,"(m)(1) Except as provided in paragraph (2) of this subsection, the Board, or an administrative law judge or other employee of the Board designated to hear a case arising under section 1215, may require payment by the agency where the prevailing party was employed or had applied for employment at the time of the events giving rise to the case of reasonable attorney fees incurred by an employee or applicant for employment if the employee or applicant is the prevailing party and the Board, administrative law judge, or other employee (as the case may be) determines that payment by the agency is warranted in the interest of justice, including any case in which a prohibited personnel practice was engaged in by the agency or any case in which the agency's action was clearly without merit."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/1204?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1204. Powers and functions of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"0":"3, 3"}},{"t":"usc","label":"5 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/5/2302","by":{"0":"3"}},{"t":"usc","label":"5 U.S.C. § 4303","url":"https://www.law.cornell.edu/uscode/text/5/4303","subs":["(e)"],"by":{"0":"2"}},{"t":"usc","label":"5 U.S.C. § 7512","url":"https://www.law.cornell.edu/uscode/text/5/7512","stext":{"head":"§7512. Actions covered","paras":[[0,"This subchapter applies to—"],[1,"(1) a removal;"],[1,"(2) a suspension for more than 14 days;"],[1,"(3) a reduction in grade;"],[1,"(4) a reduction in pay; and"],[1,"(5) a furlough of 30 days or less;"],[0,"but does not apply to—"],[1,"(A) a suspension or removal under section 7532 of this title,"],[1,"(B) a reduction-in-force action under section 3502 of this title,"],[1,"(C) the reduction in grade of a supervisor or manager who has not completed the probationary period under section 3321(a)(2) of this title if such reduction is to the grade held immediately before becoming such a supervisor or manager,"],[1,"(D) a reduction in grade or removal under section 4303 of this title,"],[1,"(E) an action initiated under section 1215 or 7521 of this title, or"],[1,"(F) a suitability action taken by the Office under regulations prescribed by the Office, subject to the rules prescribed by the President under this title for the administration of the competitive service."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7512?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7512. Actions covered","tname":"Government Organization and Employees","by":{"0":"3"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(a)","(d)"],"by":{"0":"3, 2, 3"}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","subs":["(a)","(c)(1)","(k)"],"stext":{"head":"§7701. Appellate procedures","paras":[[0,"(a) An employee, or applicant for employment, may submit an appeal to the Merit Systems Protection Board from any action which is appealable to the Board under any law, rule, or regulation. An appellant shall have the right—"],[1,"(1) to a hearing for which a transcript will be kept; and"],[1,"(2) to be represented by an attorney or other representative."],[0,"Appeals shall be processed in accordance with regulations prescribed by the Board."],[0,"(b)(1) The Board may hear any case appealed to it or may refer the case to an administrative law judge appointed under section 3105 of this title or other employee of the Board designated by the Board to hear such cases, except that in any case involving a removal from the service, the case shall be heard by the Board, an employee experienced in hearing appeals, or an administrative law judge. The Board, administrative law judge, or other employee (as the case may be) shall make a decision after receipt of the written representations of the parties to the appeal and after opportunity for a hearing under subsection (a)(1) of this section. A copy of the decision shall be furnished to each party to the appeal and to the Office of Personnel Management."],[0,"(2)(A) If an employee or applicant for employment is the prevailing party in an appeal under this subsection, the employee or applicant shall be granted the relief provided in the decision effective upon the making of the decision, and remaining in effect pending the outcome of any petition for review under subsection (e), unless—"],[1,"(i) the deciding official determines that the granting of such relief is not appropriate; or"],[1,"(ii)(I) the relief granted in the decision provides that such employee or applicant shall return or be present at the place of employment during the period pending the outcome of any petition for review under subsection (e); and"],[1,"(II) the employing agency, subject to the provisions of subparagraph (B), determines that the return or presence of such employee or applicant is unduly disruptive to the work environment."],[0,"(B) If an agency makes a determination under subparagraph (A)(ii)(II) that prevents the return or presence of an employee at the place of employment, such employee shall receive pay, compensation, and all other benefits as terms and conditions of employment during the period pending the outcome of any petition for review under subsection (e)."],[0,"(C) Nothing in the provisions of this paragraph may be construed to require any award of back pay or attorney fees be paid before the decision is final."],[0,"(3) With respect to an appeal from an adverse action covered by subchapter V of chapter 75, authority to mitigate the personnel action involved shall be available, subject to the same standards as would apply in an appeal involving an action covered by subchapter II of chapter 75 with respect to which mitigation authority under this section exists."],[0,"(c)(1) Subject to paragraph (2) of this subsection, the decision of the agency shall be sustained under subsection (b) only if the agency's decision—"],[1,"(A) in the case of an action based on unacceptable performance described in section 4303, is supported by substantial evidence; or"],[1,"(B) in any other case, is supported by a preponderance of the evidence."],[0,"(2) Notwithstanding paragraph (1), the agency's decision may not be sustained under subsection (b) of this section if the employee or applicant for employment—"],[1,"(A) shows harmful error in the application of the agency's procedures in arriving at such decision;"],[1,"(B) shows that the decision was based on any prohibited personnel practice described in section 2302(b) of this title; or"],[1,"(C) shows that the decision was not in accordance with law."],[0,"(d)(1) In any case in which—"],[1,"(A) the interpretation or application of any civil service law, rule, or regulation, under the jurisdiction of the Office of Personnel Management is at issue in any proceeding under this section; and"],[1,"(B) the Director of the Office of Personnel Management is of the opinion that an erroneous decision would have a substantial impact on any civil service law, rule, or regulation under the jurisdiction of the Office;"],[0,"the Director may as a matter of right intervene or otherwise participate in that proceeding before the Board. If the Director exercises his right to participate in a proceeding before the Board, he shall do so as early in the proceeding as practicable. Nothing in this title shall be construed to permit the Office to interfere with the independent decisionmaking of the Merit Systems Protection Board."],[0,"(2) The Board shall promptly notify the Director whenever the interpretation of any civil service law, rule, or regulation under the jurisdiction of the Office is at issue in any proceeding under this section."],[0,"(e)(1) Except as provided in section 7702 of this title, any decision under subsection (b) of this section shall be final unless—"],[1,"(A) a party to the appeal or the Director petitions the Board for review within 30 days after the receipt of the decision; or"],[1,"(B) the Board reopens and reconsiders a case on its own motion."],[0,"The Board, for good cause shown, may extend the 30-day period referred to in subparagraph (A) of this paragraph. One member of the Board may grant a petition or otherwise direct that a decision be reviewed by the full Board. The preceding sentence shall not apply if, by law, a decision of an administrative law judge is required to be acted upon by the Board."],[0,"(2) The Director may petition the Board for a review under paragraph (1) of this subsection only if the Director is of the opinion that the decision is erroneous and will have a substantial impact on any civil service law, rule, or regulation under the jurisdiction of the Office."],[0,"(f) The Board, or an administrative law judge or other employee of the Board designated to hear a case, may—"],[1,"(1) consolidate appeals filed by two or more appellants, or"],[1,"(2) join two or more appeals filed by the same appellant and hear and decide them concurrently,"],[0,"if the deciding official or officials hearing the cases are of the opinion that the action could result in the appeals' being processed more expeditiously and would not adversely affect any party."],[0,"(g)(1) Except as provided in paragraph (2) of this subsection, the Board, or an administrative law judge or other employee of the Board designated to hear a case, may require payment by the agency involved of reasonable attorney fees incurred by an employee or applicant for employment if the employee or applicant is the prevailing party and the Board, administrative law judge, or other employee (as the case may be) determines that payment by the agency is warranted in the interest of justice, including any case in which a prohibited personnel practice was engaged in by the agency or any case in which the agency's action was clearly without merit."],[0,"(2) If an employee or applicant for employment is the prevailing party and the decision is based on a finding of discrimination prohibited under section 2302(b)(1) of this title, the payment of attorney fees shall be in accordance with the standards prescribed under section 706(k) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–5(k))."],[0,"(h) The Board may, by regulation, provide for one or more alternative methods for settling matters subject to the appellate jurisdiction of the Board which shall be applicable at the election of an applicant for employment or of an employee who is not in a unit for which a labor organization is accorded exclusive recognition, and shall be in lieu of other procedures provided for under this section. A decision under such a method shall be final, unless the Board reopens and reconsiders a case at the request of the Office of Personnel Management under subsection (e) of this section."],[0,"(i)(1) Upon the submission of any appeal to the Board under this section, the Board, through reference to such categories of cases, or other means, as it determines appropriate, shall establish and announce publicly the date by which it intends to complete action on the matter. Such date shall assure expeditious consideration of the appeal, consistent with the interests of fairness and other priorities of the Board. If the Board fails to complete action on the appeal by the announced date, and the expected delay will exceed 30 days, the Board shall publicly announce the new date by which it intends to complete action on the appeal."],[0,"(2) Not later than March 1 of each year, the Board shall submit to the Congress a report describing the number of appeals submitted to it during the preceding fiscal year, the number of appeals on which it completed action during that year, and the number of instances during that year in which it failed to conclude a proceeding by the date originally announced, together with an explanation of the reasons therefor."],[0,"(3) The Board shall by rule indicate any other category of significant Board action which the Board determines should be subject to the provisions of this subsection."],[0,"(4) It shall be the duty of the Board, an administrative law judge, or employee designated by the Board to hear any proceeding under this section to expedite to the extent practicable that proceeding."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7701?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§7701. Appellate procedures","tname":"Government Organization and Employees","by":{"0":"3, 22, 3, 5, 3, 22"}},{"t":"usc","label":"5 U.S.C. § 7702","url":"https://www.law.cornell.edu/uscode/text/5/7702","subs":["(a)(1)","(a)(1)(A)","(a)(2)","(a)(2)(A)","(a)(3)","(a)(3)(A)","(b)","(b)(1)","(b)(3)(B)(i)","(b)(5)","(d)(1)","(d)(6)","(e)(1)(A)","(e)(1)(B)"],"stext":{"head":"§7702. Actions involving discrimination","paras":[[0,"(a)(1) Notwithstanding any other provision of law, and except as provided in paragraph (2) of this subsection, in the case of any employee or applicant for employment who—"],[1,"(A) has been affected by an action which the employee or applicant may appeal to the Merit Systems Protection Board, and"],[1,"(B) alleges that a basis for the action was discrimination prohibited by—"],[2,"(i) section 717 of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16),"],[2,"(ii) section 6(d) of the Fair Labor Standards Act of 1938 (29 U.S.C. 206(d)),"],[2,"(iii) section 501 of the Rehabilitation Act of 1973 (29 U.S.C. 791),"],[2,"(iv) sections 12 and 15 of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 631, 633a), or"],[2,"(v) any rule, regulation, or policy directive prescribed under any provision of law described in clauses (i) through (iv) of this subparagraph,"],[0,"the Board shall, within 120 days of the filing of the appeal, decide both the issue of discrimination and the appealable action in accordance with the Board's appellate procedures under section 7701 of this title and this section."],[0,"(2) In any matter before an agency which involves—"],[1,"(A) any action described in paragraph (1)(A) of this subsection; and"],[1,"(B) any issue of discrimination prohibited under any provision of law described in paragraph (1)(B) of this subsection;"],[0,"the agency shall resolve such matter within 120 days. The decision of the agency in any such matter shall be a judicially reviewable action unless the employee appeals the matter to the Board under paragraph (1) of this subsection."],[0,"(3) Any decision of the Board under paragraph (1) of this subsection shall be a judicially reviewable action as of—"],[1,"(A) the date of issuance of the decision if the employee or applicant does not file a petition with the Equal Employment Opportunity Commission under subsection (b)(1) of this section, or"],[1,"(B) the date the Commission determines not to consider the decision under subsection (b)(2) of this section."],[0,"(b)(1) An employee or applicant may, within 30 days after notice of the decision of the Board under subsection (a)(1) of this section, petition the Commission to consider the decision."],[0,"(2) The Commission shall, within 30 days after the date of the petition, determine whether to consider the decision. A determination of the Commission not to consider the decision may not be used as evidence with respect to any issue of discrimination in any judicial proceeding concerning that issue."],[0,"(3) If the Commission makes a determination to consider the decision, the Commission shall, within 60 days after the date of the determination, consider the entire record of the proceedings of the Board and, on the basis of the evidentiary record before the Board, as supplemented under paragraph (4) of this subsection, either—"],[1,"(A) concur in the decision of the Board; or"],[1,"(B) issue in writing another decision which differs from the decision of the Board to the extent that the Commission finds that, as a matter of law—"],[2,"(i) the decision of the Board constitutes an incorrect interpretation of any provision of any law, rule, regulation, or policy directive referred to in subsection (a)(1)(B) of this section, or"],[2,"(ii) the decision involving such provision is not supported by the evidence in the record as a whole."],[0,"(4) In considering any decision of the Board under this subsection, the Commission may refer the case to the Board, or provide on its own, for the taking (within such period as permits the Commission to make a decision within the 60-day period prescribed under this subsection) of additional evidence to the extent it considers necessary to supplement the record."],[0,"(5)(A) If the Commission concurs pursuant to paragraph (3)(A) of this subsection in the decision of the Board, the decision of the Board shall be a judicially reviewable action."],[0,"(B) If the Commission issues any decision under paragraph (3)(B) of this subsection, the Commission shall immediately refer the matter to the Board."],[0,"(c) Within 30 days after receipt by the Board of the decision of the Commission under subsection (b)(5)(B) of this section, the Board shall consider the decision and—"],[1,"(1) concur and adopt in whole the decision of the Commission; or"],[1,"(2) to the extent that the Board finds that, as a matter of law, (A) the Commission decision constitutes an incorrect interpretation of any provision of any civil service law, rule, regulation or policy directive, or (B) the Commission decision involving such provision is not supported by the evidence in the record as a whole—"],[2,"(i) reaffirm the initial decision of the Board; or"],[2,"(ii) reaffirm the initial decision of the Board with such revisions as it determines appropriate."],[0,"If the Board takes the action provided under paragraph (1), the decision of the Board shall be a judicially reviewable action."],[0,"(d)(1) If the Board takes any action under subsection (c)(2) of this section, the matter shall be immediately certified to a special panel described in paragraph (6) of this subsection. Upon certification, the Board shall, within 5 days (excluding Saturdays, Sundays, and holidays), transmit to the special panel the administrative record in the proceeding, including—"],[1,"(A) the factual record compiled under this section,"],[1,"(B) the decisions issued by the Board and the Commission under this section, and"],[1,"(C) any transcript of oral arguments made, or legal briefs filed, before the Board or the Commission."],[0,"(2)(A) The special panel shall, within 45 days after a matter has been certified to it, review the administrative record transmitted to it and, on the basis of the record, decide the issues in dispute and issue a final decision which shall be a judicially reviewable action."],[0,"(B) The special panel shall give due deference to the respective expertise of the Board and Commission in making its decision."],[0,"(3) The special panel shall refer its decision under paragraph (2) of this subsection to the Board and the Board shall order any agency to take any action appropriate to carry out the decision."],[0,"(4) The special panel shall permit the employee or applicant who brought the complaint and the employing agency to appear before the panel to present oral arguments and to present written arguments with respect to the matter."],[0,"(5) Upon application by the employee or applicant, the Commission may issue such interim relief as it determines appropriate to mitigate any exceptional hardship the employee or applicant might otherwise incur as a result of the certification of any matter under this subsection, except that the Commission may not stay, or order any agency to review on an interim basis, the action referred to in subsection (a)(1) of this section."],[0,"(6)(A) Each time the Board takes any action under subsection (c)(2) of this section, a special panel shall be convened which shall consist of—"],[1,"(i) an individual appointed by the President, by and with the advice and consent of the Senate, to serve for a term of 6 years as chairman of the special panel each time it is convened;"],[1,"(ii) one member of the Board designated by the Chairman of the Board each time a panel is convened; and"],[1,"(iii) one member of the Commission designated by the Chairman of the Commission each time a panel is convened."],[0,"The chairman of the special panel may be removed by the President only for inefficiency, neglect of duty, or malfeasance in office."],[0,"(B) The chairman is entitled to pay at a rate equal to the maximum annual rate of basic pay payable under the General Schedule for each day he is engaged in the performance of official business on the work of the special panel."],[0,"(C) The Board and the Commission shall provide such administrative assistance to the special panel as may be necessary and, to the extent practicable, shall equally divide the costs of providing the administrative assistance."],[0,"(e)(1) Notwithstanding any other provision of law, if at any time after—"],[1,"(A) the 120th day following the filing of any matter described in subsection (a)(2) of this section with an agency, there is no judicially reviewable action under this section or an appeal under paragraph (2) of this subsection;"],[1,"(B) the 120th day following the filing of an appeal with the Board under subsection (a)(1) of this section, there is no judicially reviewable action (unless such action is not as the result of the filing of a petition by the employee under subsection (b)(1) of this section); or"],[1,"(C) the 180th day following the filing of a petition with the Equal Employment Opportunity Commission under subsection (b)(1) of this section, there is no final agency action under subsection (b), (c), or (d) of this section;"],[0,"an employee shall be entitled to file a civil action to the same extent and in the same manner as provided in section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), or section 16(b) of the Fair Labor Standards Act of 1938 (29 U.S.C. 216(b))."],[0,"(2) If, at any time after the 120th day following the filing of any matter described in subsection (a)(2) of this section with an agency, there is no judicially reviewable action, the employee may appeal the matter to the Board under subsection (a)(1) of this section."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7702?type=usc&year=mostrecent&link-type=html"},"op":15,"ar":6,"head":"§7702. Actions involving discrimination","tname":"Government Organization and Employees","by":{"0":"passim, passim, 4, 21, 4, passim, 5, 21, 23, 7, 15, 23, 33, 23, 36, 24, 41, 41, 41, 42, 16, 27, 28, 37, 38"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(a)","(a)(1)","(a)(2)","(b)","(b)(1)","(b)(2)","(c)","(d)"],"stext":{"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","paras":[[0,"(a)(1) Any employee or applicant for employment adversely affected or aggrieved by a final order or decision of the Merit Systems Protection Board may obtain judicial review of the order or decision."],[0,"(2) The Board shall be named respondent in any proceeding brought pursuant to this subsection, unless the employee or applicant for employment seeks review of a final order or decision on the merits on the underlying personnel action or on a request for attorney fees, in which case the agency responsible for taking the personnel action shall be the respondent."],[0,"(b)(1)(A) Except as provided in subparagraph (B) and paragraph (2) of this subsection, a petition to review a final order or final decision of the Board shall be filed in the United States Court of Appeals for the Federal Circuit. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(B) A petition to review a final order or final decision of the Board that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) shall be filed in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(2) Cases of discrimination subject to the provisions of section 7702 of this title shall be filed under section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), and section 16(b) of the Fair Labor Standards Act of 1938, as amended (29 U.S.C. 216(b)), as applicable. Notwithstanding any other provision of law, any such case filed under any such section must be filed within 30 days after the date the individual filing the case received notice of the judicially reviewable action under such section 7702."],[0,"(c) In any case filed in the United States Court of Appeals for the Federal Circuit, the court shall review the record and hold unlawful and set aside any agency action, findings, or conclusions found to be—"],[1,"(1) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(2) obtained without procedures required by law, rule, or regulation having been followed; or"],[1,"(3) unsupported by substantial evidence;"],[0,"except that in the case of discrimination brought under any section referred to in subsection (b)(2) of this section, the employee or applicant shall have the right to have the facts subject to trial de novo by the reviewing court."],[0,"(d)(1) Except as provided under paragraph (2), this paragraph shall apply to any review obtained by the Director of the Office of Personnel Management. The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the Court of Appeals. The granting of the petition for judicial review shall be at the discretion of the Court of Appeals."],[0,"(2) This paragraph shall apply to any review obtained by the Director of the Office of Personnel Management that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D). The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the court of appeals. The granting of the petition for judicial review shall be at the discretion of the court of appeals."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7703?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"0":"passim, 24, 24, 24, 26, 39, 41, 6, 20, 26, 29, 30, 7, passim, 7, 8, 6, 37"}},{"t":"law","label":"Pub. L. No. 97-164","url":"https://www.govinfo.gov/link/statute/96/25","by":{"0":"19"}},{"t":"usc","label":"29 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/29/701","by":{"0":"13, 44"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(9)"],"by":{"0":"6, 20"}}]};